import subprocess, json, os, statistics
def run_once(epochs):
    env = os.environ.copy()
    env['RUN_TAG'] = '0'
    cmd = ['python3', 'train.py', '--n', '1200', '--positive_rate', '0.3', '--label_noise', '0.05', '--split', '0.8', '--normalize', 'none', '--epochs', str(epochs), '--batch_size', '32', '--lr', '0.05', '--lr_schedule', 'const', '--weight_decay', '0.0', '--class_weight', 'none', '--threshold', '0.5', '--data_seed', '7', '--out', '/tmp/tmp.json']
    result = subprocess.run(cmd, env=env, capture_output=True, text=True)
    if result.returncode != 0:
        return None
    out = json.loads(result.stdout.strip())
    return out['test_accuracy'], out['balanced_accuracy']
